  for(int i=0;i<blocks.length();i++){need(normalized.containsKey(i),"missing-block");JSONObject r=normalized.get(i),b=blocks.getJSONObject(i);if(i==0)provenance=r.getString("provenance");need(r.getString("provenance").equals(provenance),"mixed-provenance");summaries.add(r.getString("summary"));JSONArray edges=r.getJSONArray("relations");for(int j=0;j<edges.length();j++){Object v=edges.get(j);if(seen.add(ResearchRuns.canonical(v)))relations.put(v);}evidence.put(new JSONObject().put("index",i).put("start",b.get("start")).put("end",b.get("end")).put("blockHash",b.get("blockHash")).put("responseHash",r.get("responseHash")));ordered.put(copy(envelopes.get(i)));}
