  return new JSONObject().put("schema","native-creator-ai-candidate/v1").put("sourceId",p.get("sourceId")).put("recordHash",p.get("recordHash")).put("planHash",p.get("planHash")).put("provenance",provenance).put("status",relations.length()==0?"complete_empty":"complete_with_relations").put("responses",ordered).put("analysis",a);
